local ADDON_NAME, NS = ...

-- Gear audit helpers (kb/addons/Bulwark-Utilities.md "Idea: Gear audit"): which enchants fit a slot and how much
-- total avoidance each adds over the enchant already there. Ranked by avoidance gain, NOT Best-in-Slot; stamina is
-- the second number and only breaks ties. Pure functions on NS.EnchantData (generated by tools/gen-enchants.ps1) and
-- an Avoidance snapshot, so they test headlessly.
local Enchants = {}
NS.Enchants = Enchants

local NOISE = 0.005     -- % avoidance: smaller gains are rounding, not a better enchant

-- Stats of an enchant ID (empty when unknown: an enchant with nothing a tank uses).
function Enchants.Stats(enchantID)
    local data = NS.EnchantData
    return enchantID and data and data.stats[enchantID] or {}
end

-- Enchant ID from an item link ("item:<itemID>:<enchantID>:..."), nil when the item has none.
function Enchants.FromLink(link)
    if type(link) ~= "string" then return nil end
    local id = tonumber(link:match("item:%-?%d+:(%-?%d*)") or "")
    if id and id > 0 then return id end
    return nil
end

-- What the item in the slot must be. item = { classID, subClassID, equipLoc, ilvl } (C_Item.GetItemInfoInstant +
-- C_Item.GetDetailedItemLevelInfo).
local REQ = {
    shield = function(item) return item.classID == 4 and item.subClassID == 6 end,
    holdable = function(item) return item.equipLoc == "INVTYPE_HOLDABLE" end,
    ["2h"] = function(item) return item.equipLoc == "INVTYPE_2HWEAPON" end,
    weapon = function(item) return item.classID == 2 end,
}

-- Can this source go on the item in this slot, for a player of this level?
function Enchants.Fits(src, slot, item, level)
    local inSlot = false
    for _, s in ipairs(src.slots) do
        if s == slot then inSlot = true; break end
    end
    if not inSlot or not item then return false end
    if src.req and not (REQ[src.req] and REQ[src.req](item)) then return false end
    if src.minIlvl and not (item.ilvl and item.ilvl >= src.minIlvl) then return false end
    if src.reqLevel and not (level and level >= src.reqLevel) then return false end
    return true
end

local function AddDelta(delta, stats, sign)
    delta.defense = (delta.defense or 0) + sign * (stats.def or 0)
    delta.agility = (delta.agility or 0) + sign * (stats.agi or 0)
    delta.dodge = (delta.dodge or 0) + sign * (stats.dodge or 0)
    delta.parry = (delta.parry or 0) + sign * (stats.parry or 0)
    delta.block = (delta.block or 0) + sign * (stats.block or 0)
end

-- Does block chance count for nothing in this character's ranking? True for a Warrior who knows Shield Block and
-- wears a shield. Forever's Shield Block (2 blocks, 7 s, 5 s cooldown, off the GCD, paid back by Shield
-- Specialization rage [data]) used on cooldown blocks almost every swing that isn't dodged, parried or missed, so
-- 1 % base block is worth only 0-4 % of 1 % dodge [simulation, kb/addons/Bulwark-Utilities.md "Research: is there
-- an avoidance breakpoint"]. Any weight above zero would still rank Shield - Lesser Block over a stamina enchant
-- (stamina only breaks ties), so it counts as zero. Paladins keep it: Holy Shield (+30 %) doesn't fill the table.
function Enchants.IgnoresBlock(snap)
    return snap and snap.hasShield and snap.known and snap.known.shieldBlock and true or false
end

-- Total avoidance (%) and stamina gained by replacing currentID with enchantID. snap = Avoidance.Read() result;
-- opts = Avoidance.Compute options (attacker level offset). Block chance is left out when IgnoresBlock(snap).
function Enchants.Gain(snap, enchantID, currentID, opts)
    local new, cur = Enchants.Stats(enchantID), Enchants.Stats(currentID)
    local delta = {}
    AddDelta(delta, new, 1)
    AddDelta(delta, cur, -1)
    local Av = NS.Avoidance
    local before = Av.Compute(snap, opts)
    local after = Av.Compute(Av.Apply(snap, delta), opts)
    local gain = after.total - before.total
    if Enchants.IgnoresBlock(snap) then gain = gain - (after.raw.block - before.raw.block) end
    return gain, (new.sta or 0) - (cur.sta or 0)
end

-- Caster enchants (generated `caster = true`: spell power or a spell proc, no avoidance) are threat enchants for a
-- Paladin, whose threat stat is spell power (kb/tanks/paladin.md). Nobody else is offered them.
function Enchants.ForCaster()
    return NS.playerClass == "PALADIN"
end

-- Enchants that fit the item in a slot, best avoidance gain first, then stamina, then spell power. One entry per
-- enchant: { enchant, gain, stamina, sp, current, sources = { source rows } }.
function Enchants.ForSlot(snap, slot, item, currentID, opts)
    local list, byEnchant = {}, {}
    local data = NS.EnchantData
    if not data then return list end
    local caster = Enchants.ForCaster()
    for _, src in ipairs(data.sources) do
        if Enchants.Fits(src, slot, item, snap.level) and (caster or not Enchants.Stats(src.enchant).caster) then
            local entry = byEnchant[src.enchant]
            if not entry then
                local gain, stamina = Enchants.Gain(snap, src.enchant, currentID, opts)
                entry = { enchant = src.enchant, gain = gain, stamina = stamina, sp = Enchants.Stats(src.enchant).sp or 0,
                          current = src.enchant == currentID, sources = {} }
                byEnchant[src.enchant] = entry
                list[#list + 1] = entry
            end
            entry.sources[#entry.sources + 1] = src
        end
    end
    table.sort(list, function(a, b)
        if math.abs(a.gain - b.gain) > NOISE then return a.gain > b.gain end
        if a.stamina ~= b.stamina then return a.stamina > b.stamina end
        if a.sp ~= b.sp then return a.sp > b.sp end
        return a.enchant < b.enchant
    end)
    return list
end

-- Verdict for a slot of an Avoidance set: "missing" (no enchant, one would fit), "weaker" (another adds avoidance)
-- or nil (fine, or nothing fits). Also returns the ranked list.
function Enchants.Verdict(snap, slot, item, currentID, opts)
    local list = Enchants.ForSlot(snap, slot, item, currentID, opts)
    if #list == 0 then return nil, list end
    if not currentID then return "missing", list end
    if list[1].gain > NOISE then return "weaker", list end
    return nil, list
end
